import { spawnSync } from 'node:child_process';

const BIN = '/workspace/dataset/test1_executable';

function b64urlDecode(s) {
  const pad = (4 - (s.length % 4)) % 4;
  return Buffer.from(s + '='.repeat(pad), 'base64');
}

export function run(argvBufs) {
  const r = spawnSync(BIN, argvBufs, { encoding: 'buffer' });
  return {
    status: r.status,
    stdout: r.stdout,
    stderr: r.stderr,
  };
}

export function probe(valueBuf, label) {
  const r = run([Buffer.from('--payload'), Buffer.isBuffer(valueBuf) ? valueBuf : Buffer.from(valueBuf, 'utf8')]);
  const out = { label, status: r.status };
  if (r.status !== 0) {
    out.stderr = r.stderr.toString('utf8');
    return out;
  }
  const tok = r.stdout.toString('latin1').replace(/\n$/, '');
  const parts = tok.split('.');
  out.token = tok;
  out.header = b64urlDecode(parts[0]).toString('utf8');
  out.payloadRaw = b64urlDecode(parts[1]);
  out.payload = out.payloadRaw.toString('utf8');
  out.payloadHex = out.payloadRaw.toString('hex');
  out.sig = parts[2];
  out.nparts = parts.length;
  return out;
}

