import { spawnSync } from 'node:child_process';
const BIN = '/workspace/dataset/test1_executable';
function tok(args){ const r = spawnSync(BIN, args.map(a=>Buffer.isBuffer(a)?a:Buffer.from(a,'utf8')), {encoding:'buffer'}); return {s:r.status, o:r.stdout.toString('latin1').replace(/\n$/,'')}; }
const v = 'a"b\\c\té中\u{1F600}';
const a = tok(['--payload', v]);
const b = tok([Buffer.concat([Buffer.from('--payload='), Buffer.from(v,'utf8')])]);
console.log('separate  :', a.s, a.o);
console.log('equals    :', b.s, b.o);
console.log('identical :', a.o === b.o);
// abbreviation
const c = tok(['--pay', v]);
console.log('--pay     :', c.s, c.o === a.o);
// last wins
const d = tok(['--payload','x','--payload', v]);
console.log('dup last  :', d.s, d.o === a.o);
